using MermaidSharp.AutoDiagram;
using MermaidSharp.AutoDiagram.Diagrams;
using MermaidSharp.AutoDiagram.Enums;
using MermaidSharp.AutoDiagram.Options;
using MermaidSharp.Diagrams;
using MermaidSharp.Enums;
using MermaidSharp.Samples.Domain;

namespace MermaidSharp.Samples.Examples
{
    /// <summary>
    /// Provides diagrams generated by reflection with MermaidSharp.AutoDiagram.
    /// </summary>
    public static class AutoDiagramExamples
    {
        private static readonly Type[] DomainTypes =
        {
            typeof(ILoanable), typeof(LibraryItem), typeof(Book), typeof(Magazine),
            typeof(Author), typeof(Member), typeof(Loan)
        };

        public static IEnumerable<DiagramExample> Create()
        {
            yield return DomainClassDiagram();
            yield return PublicApiClassDiagram();
            yield return AssemblyDependencies();
        }

        private static DiagramExample DomainClassDiagram()
        {
            var diagram = DomainTypes.ToMermaidClassDiagram();

            return new DiagramExample(DiagramKind.AutoDiagram, "auto-class-domain", "Class diagram from types",
                "A library domain reflected with every member, inheritance, interface and association links.",
                diagram.CalculateDiagram());
        }

        private static DiagramExample PublicApiClassDiagram()
        {
            var publicOnly = new List<ClassPropertyVisibility> { ClassPropertyVisibility.Public };
            var options = new ClassDiagramOptions
            {
                PropertyOptions = new ClassPropertyOptions { IncludeVisibility = publicOnly },
                MethodOptions = new ClassMethodOptions { IncludeVisibility = publicOnly, IncludeParameters = false },
                LinkOptions = new ClassLinkOptions { IncludeLinks = ClassLinkOption.Inherited | ClassLinkOption.Interface, IncludeLinksLabels = false }
            };
            var diagram = DomainTypes.ToMermaidClassDiagram(options);

            return new DiagramExample(DiagramKind.AutoDiagram, "auto-class-public-api", "Public API only",
                "Same domain filtered to public members, without parameters, association links or labels.",
                diagram.CalculateDiagram());
        }

        private static DiagramExample AssemblyDependencies()
        {
            var assemblies = new[]
            {
                typeof(DiagramCatalog).Assembly,
                typeof(FlowchartDiagram).Assembly,
                typeof(ClassDiagramExtension).Assembly
            };
            var diagram = assemblies.ToMermaidFlowchartDiagram(new FlowchartDiagramOptions { SubgraphGroupLabel = "MermaidSharp" });

            return new DiagramExample(DiagramKind.AutoDiagram, "auto-flowchart-assemblies", "Assembly dependencies",
                "Flowchart of the MermaidSharp assemblies and their references.", diagram.CalculateDiagram());
        }
    }
}
